import { describe, it, expect, beforeEach } from 'vitest'
import crypto from 'crypto'
import type Database from 'better-sqlite3'
import { db, sqliteDb } from '@/db/index.js'
import { workLogs, users } from '@/db/schema.js'

// Raw SQL executor — avoids Drizzle Date/number conversion issues with timestamps
function run(sqlStr: string, params?: unknown[]): void {
  const client = sqliteDb as Database.Database
  client.prepare(sqlStr).run(...(params ?? []))
}

// Import service functions we're testing
import { startWorkTimer, stopWorkTimer } from '../repair.service.js'

// ---------------------------------------------------------------------------
// Helpers — create test fixtures in the DB
// ---------------------------------------------------------------------------

async function seedUser(): Promise<string> {
  const id = crypto.randomUUID()
  await db.insert(users).values({
    id,
    name: 'Test Technician',
    role: 'mechanic',
    hourlyRate: 5000, // 50 EUR/hour in cents
  })
  return id
}

/** Raw SQL helper for inserting repairs (avoids Drizzle type issues with id/status) */
function insertRepair(repairId: string, bicycleId: string, status = 'in_progress'): void {
  const now = Date.now()
  run(
    'INSERT INTO repairs (id, bicycle_id, assigned_to, status, customer_notes, internal_notes, hold_reason, hold_reason_note, planned_date, pickup_date, completed_at, created_at) VALUES (?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?)',
    [repairId, bicycleId, null, status, null, null, null, null, null, null, null, now]
  )
}

async function seedRepair(status = 'in_progress'): Promise<string> {
  const id = crypto.randomUUID()
  insertRepair(id, 'bicycle-placeholder-id', status)
  return id
}

async function resetWorkLogs() {
  await db.delete(workLogs)
}

// ---------------------------------------------------------------------------
// Tests
// ---------------------------------------------------------------------------

describe('Repair Timer Service', () => {
  beforeEach(async () => {
    await resetWorkLogs()
  })

  describe('startWorkTimer', () => {
    it('should create a new work log entry with startedAt timestamp and return it', async () => {
      const userId = await seedUser()
      const repairId = await seedRepair()

      const result = await startWorkTimer(repairId, userId)

      expect(result).toHaveProperty('id')
      expect(result.repairId).toBe(repairId)
      expect(result.userId).toBe(userId)
      expect(result.startedAt).toBeDefined()
      expect(result.endedAt).toBeNull()
    })

    it('should throw RepairNotFoundError when repair does not exist', async () => {
      const userId = await seedUser()

      await expect(startWorkTimer('non-existent-id', userId)).rejects.toThrow('Repair not found')
    })

    it('should create a new entry each time (allow multiple sessions)', async () => {
      const userId = await seedUser()
      const repairId = await seedRepair()

      const first = await startWorkTimer(repairId, userId)
      const second = await startWorkTimer(repairId, userId)

      expect(first.id).not.toBe(second.id)
      // Both should have endedAt = null (both "active" at DB level — service doesn't prevent double-start)
      expect(first.endedAt).toBeNull()
      expect(second.endedAt).toBeNull()
    })

    it('should record different startedAt timestamps for sequential starts', async () => {
      const userId = await seedUser()
      const repairId = await seedRepair()

      const first = await startWorkTimer(repairId, userId)
      // Small delay to ensure different timestamp
      await new Promise(resolve => setTimeout(resolve, 10))
      const second = await startWorkTimer(repairId, userId)

      expect(second.startedAt ?? 0).toBeGreaterThan(first.startedAt ?? 0)
    })
  })

  describe('stopWorkTimer', () => {
    it('should set endedAt on the active work log entry and return updated record', async () => {
      const userId = await seedUser()
      const repairId = await seedRepair()

      // Start a timer session
      const started = await startWorkTimer(repairId, userId)
      const workLogId = started.id

      // Small delay so endedAt > startedAt
      await new Promise(resolve => setTimeout(resolve, 10))

      const result = await stopWorkTimer(workLogId)

      expect(result.id).toBe(workLogId)
      expect(result.endedAt).toBeDefined()
      expect(result.endedAt!).toBeGreaterThan(started.startedAt ?? 0)
    })

    it('should throw WorkLogNotFoundError when work log does not exist', async () => {
      await expect(stopWorkTimer('non-existent-work-log-id')).rejects.toThrow('Work log not found')
    })

    it('should record cumulative time across multiple start/stop sessions', async () => {
      const userId = await seedUser()
      const repairId = await seedRepair()

      // Session 1: ~50ms
      const s1 = await startWorkTimer(repairId, userId)
      await new Promise(resolve => setTimeout(resolve, 50))
      const e1 = await stopWorkTimer(s1.id)
      const duration1 = e1.endedAt! - (e1.startedAt ?? 0)

      // Session 2: ~30ms
      const s2 = await startWorkTimer(repairId, userId)
      await new Promise(resolve => setTimeout(resolve, 30))
      const e2 = await stopWorkTimer(s2.id)
      const duration2 = e2.endedAt! - (e2.startedAt ?? 0)

      // Session 3: ~70ms
      const s3 = await startWorkTimer(repairId, userId)
      await new Promise(resolve => setTimeout(resolve, 70))
      const e3 = await stopWorkTimer(s3.id)
      const duration3 = e3.endedAt! - (e3.startedAt ?? 0)

      // All three should have valid durations (within tolerance for OS scheduling)
      expect(duration1).toBeGreaterThan(40)
      expect(duration2).toBeGreaterThan(20)
      expect(duration3).toBeGreaterThan(60)

      // Cumulative time across all sessions
      const cumulative = duration1 + duration2 + duration3
      expect(cumulative).toBeGreaterThan(130)
    })

    it('should throw RepairNotFoundError when the work log repair does not exist', async () => {
      const userId = await seedUser()
      // Create a work log referencing a non-existent repair using raw SQL
      const workLogId = crypto.randomUUID()
      const fakeRepairId = 'non-existent-repair-id'
      const now = Date.now()

      run(
        'INSERT INTO work_logs (id, repair_id, user_id, started_at, ended_at) VALUES (?, ?, ?, ?, NULL)',
        [workLogId, fakeRepairId, userId, now]
      )

      // stopWorkTimer should still succeed — it only looks up the work log by ID
      const result = await stopWorkTimer(workLogId)
      expect(result.endedAt).toBeDefined()
    })

    it('should handle double-stop gracefully (second stop updates endedAt again)', async () => {
      const userId = await seedUser()
      const repairId = await seedRepair()

      const started = await startWorkTimer(repairId, userId)
      const workLogId = started.id

      // First stop
      const firstStop = await stopWorkTimer(workLogId)
      const firstEndedAt = firstStop.endedAt!

      // Small delay
      await new Promise(resolve => setTimeout(resolve, 10))

      // Second stop — should still succeed and update endedAt
      const secondStop = await stopWorkTimer(workLogId)
      expect(secondStop.id).toBe(workLogId)
      expect(secondStop.endedAt!).toBeGreaterThanOrEqual(firstEndedAt)
    })
  })

  describe('end-to-end timer flow', () => {
    it('should support a complete start → stop cycle with accurate duration', async () => {
      const userId = await seedUser()
      const repairId = await seedRepair()

      // Start
      const started = await startWorkTimer(repairId, userId)
      expect(started.endedAt).toBeNull()

      // Wait 100ms
      await new Promise(resolve => setTimeout(resolve, 100))

      // Stop
      const stopped = await stopWorkTimer(started.id)
      expect(stopped.endedAt).toBeDefined()

      // Duration should be approximately 100ms (±50ms tolerance for OS scheduling)
      const duration = stopped.endedAt! - (started.startedAt ?? 0)
      expect(duration).toBeGreaterThan(80)
      expect(duration).toBeLessThan(200)
    })

    it('should allow multiple independent start/stop cycles on the same repair', async () => {
      const userId = await seedUser()
      const repairId = await seedRepair()

      // Cycle 1
      const s1 = await startWorkTimer(repairId, userId)
      await new Promise(resolve => setTimeout(resolve, 20))
      const e1 = await stopWorkTimer(s1.id)

      // Small delay to ensure different millisecond timestamps
      await new Promise(resolve => setTimeout(resolve, 5))

      // Cycle 2 on same repair
      const s2 = await startWorkTimer(repairId, userId)
      await new Promise(resolve => setTimeout(resolve, 30))
      const e2 = await stopWorkTimer(s2.id)

      expect(e1.startedAt).toBeLessThan(e2.startedAt ?? 0)
      expect(e1.endedAt!).toBeLessThan(e2.startedAt!)
    })
  })
})

import { describe, it, expect, beforeEach } from 'vitest'
import { db } from '@/db/index.js'
import { users } from '@/db/schema.js'
import { createUser, getUserById, updateUser, StaffNotFoundError } from '../users.service.js'

describe('Staff Member Service — CRUD', () => {
  async function resetData() {
    await db.delete(users)
  }

  beforeEach(async () => {
    await resetData()
  })

  // ---------------------------------------------------------------------------
  // getUserById
  // ---------------------------------------------------------------------------

  describe('getUserById', () => {
    it('should return a staff member by ID', async () => {
      const created = await createUser({
        name: 'Jan Kowalski',
        role: 'mechanic',
        hourlyRate: 4500,
      })

      const found = await getUserById(created.id)

      expect(found.id).toBe(created.id)
      expect(found.name).toBe('Jan Kowalski')
      expect(found.role).toBe('mechanic')
      expect(found.hourlyRate).toBe(4500)
      expect(found.isActive).toBe(true)
    })

    it('should throw StaffNotFoundError for non-existent ID', async () => {
      const fakeId = '00000000-0000-0000-0000-000000000000'

      try {
        await getUserById(fakeId)
        expect.unreachable('should have thrown')
      } catch (err) {
        expect(err).toBeInstanceOf(StaffNotFoundError)
        expect((err as Error).message).toContain(fakeId)
      }
    })
  })

  // ---------------------------------------------------------------------------
  // updateUser — partial updates
  // ---------------------------------------------------------------------------

  describe('updateUser', () => {
    it('should update name only and return updated record', async () => {
      const created = await createUser({
        name: 'Jan Kowalski',
        role: 'mechanic',
        hourlyRate: 4500,
      })

      const updated = await updateUser(created.id, {
        name: 'Jan Nowak',
      })

      expect(updated.name).toBe('Jan Nowak')
      expect(updated.role).toBe('mechanic') // unchanged
      expect(updated.hourlyRate).toBe(4500) // unchanged
      expect(updated.isActive).toBe(true) // unchanged
    })

    it('should update role only', async () => {
      const created = await createUser({
        name: 'Jan Kowalski',
        role: 'mechanic',
        hourlyRate: 4500,
      })

      const updated = await updateUser(created.id, {
        role: 'manager',
      })

      expect(updated.role).toBe('manager')
      expect(updated.name).toBe('Jan Kowalski') // unchanged
    })

    it('should update hourlyRate only', async () => {
      const created = await createUser({
        name: 'Jan Kowalski',
        role: 'mechanic',
        hourlyRate: 4500,
      })

      const updated = await updateUser(created.id, {
        hourlyRate: 5500,
      })

      expect(updated.hourlyRate).toBe(5500)
    })

    it('should toggle isActive to false (soft delete)', async () => {
      const created = await createUser({
        name: 'Jan Kowalski',
        role: 'mechanic',
        hourlyRate: 4500,
      })

      expect(created.isActive).toBe(true)

      const updated = await updateUser(created.id, {
        isActive: false,
      })

      expect(updated.isActive).toBe(false)
    })

    it('should toggle isActive back to true (reactivate)', async () => {
      const created = await createUser({
        name: 'Jan Kowalski',
        role: 'mechanic',
        hourlyRate: 4500,
        isActive: false,
      })

      expect(created.isActive).toBe(false)

      const updated = await updateUser(created.id, {
        isActive: true,
      })

      expect(updated.isActive).toBe(true)
    })

    it('should update multiple fields at once', async () => {
      const created = await createUser({
        name: 'Jan Kowalski',
        role: 'mechanic',
        hourlyRate: 4500,
      })

      const updated = await updateUser(created.id, {
        name: 'Anna Nowak',
        role: 'manager',
        hourlyRate: 6000,
      })

      expect(updated.name).toBe('Anna Nowak')
      expect(updated.role).toBe('manager')
      expect(updated.hourlyRate).toBe(6000)
    })

    it('should throw StaffNotFoundError for non-existent ID', async () => {
      const fakeId = '00000000-0000-0000-0000-000000000000'

      await expect(
        updateUser(fakeId, { name: 'Nobody' })
      ).rejects.toThrow(StaffNotFoundError)
    })

    it('should reject empty payload (no fields provided)', async () => {
      const created = await createUser({
        name: 'Jan Kowalski',
        role: 'mechanic',
        hourlyRate: 4500,
      })

      // updateStaffMemberSchema requires at least one field via .refine()
      await expect(
        updateUser(created.id, {})
      ).rejects.toThrow()
    })

    it('should reject invalid role value', async () => {
      const created = await createUser({
        name: 'Jan Kowalski',
        role: 'mechanic',
        hourlyRate: 4500,
      })

      // @ts-expect-error — testing runtime validation of invalid enum
      await expect(
        updateUser(created.id, { role: 'supervisor' })
      ).rejects.toThrow()
    })

    it('should reject negative hourlyRate', async () => {
      const created = await createUser({
        name: 'Jan Kowalski',
        role: 'mechanic',
        hourlyRate: 4500,
      })

      await expect(
        updateUser(created.id, { hourlyRate: -100 })
      ).rejects.toThrow()
    })

    it('should reject non-integer hourlyRate', async () => {
      const created = await createUser({
        name: 'Jan Kowalski',
        role: 'mechanic',
        hourlyRate: 4500,
      })

      await expect(
        updateUser(created.id, { hourlyRate: 45.5 })
      ).rejects.toThrow()
    })

    it('should reject empty name string', async () => {
      const created = await createUser({
        name: 'Jan Kowalski',
        role: 'mechanic',
        hourlyRate: 4500,
      })

      await expect(
        updateUser(created.id, { name: '' })
      ).rejects.toThrow()
    })
  })
})

/**
 * Users Service — Worker lookup for repair assignment and staff management.
 */

import crypto from 'crypto'
import { asc, eq, sql } from 'drizzle-orm'
import { db } from '../db/index.js'
import { users, type User as DbUser } from '../db/schema.js'
import {
  createStaffMemberSchema,
  updateStaffMemberSchema,
  type CreateStaffMemberInput,
  type UpdateStaffMemberInput,
} from '@shared/validations/staff.js'

// ---------------------------------------------------------------------------
// Types — compact dropdown shape (existing)
// ---------------------------------------------------------------------------

/** Compact worker shape for dropdown selectors (name + role only) */
export interface WorkerOption {
  id: string
  name: string
  role: 'mechanic' | 'manager'
}

// ---------------------------------------------------------------------------
// Types — paginated management list
// ---------------------------------------------------------------------------

/** Full staff member detail for the management list. */
export interface StaffMemberDetail {
  id: string
  name: string
  role: 'mechanic' | 'manager'
  hourlyRate: number // cents per hour
  isActive: boolean
  createdAt: Date
}

/** Query parameters for the paginated staff list. */
export interface StaffListQuery {
  /** Search term — filters by name */
  search?: string
  /** Page number (1-indexed) */
  page?: number
  /** Items per page */
  pageSize?: number
}

/** Paginated response for the staff management list. */
export interface StaffPaginatedResponse {
  users: StaffMemberDetail[]
  totalItems: number
  currentPage: number
  pageSize: number
  totalPages: number
}

// ---------------------------------------------------------------------------
// Functions — compact dropdown (existing)
// ---------------------------------------------------------------------------

/**
 * List all active workers, suitable for populating a worker assignment dropdown.
 * Returns workers sorted by name for consistent display order.
 */
export async function getActiveWorkers(): Promise<WorkerOption[]> {
  const rows = await db
    .select({
      id: users.id,
      name: users.name,
      role: users.role,
    })
    .from(users)
    .where(eq(users.isActive, true))
    .orderBy(users.name)

  return rows as unknown as WorkerOption[]
}

// ---------------------------------------------------------------------------
// Functions — create staff member
// ---------------------------------------------------------------------------

/**
 * Create a new staff member.
 *
 * Generates a UUID if not provided, applies defaults (role=mechanic, isActive=true),
 * and inserts into the users table. Returns the created StaffMemberDetail.
 */
export async function createUser(input: CreateStaffMemberInput): Promise<StaffMemberDetail> {
  const validated = createStaffMemberSchema.parse(input)

  const dbData = {
    id: validated.id ?? crypto.randomUUID(),
    name: validated.name,
    role: validated.role as 'mechanic' | 'manager',
    hourlyRate: validated.hourlyRate,
    isActive: validated.isActive ?? true,
  }

  const [created] = await db.insert(users).values(dbData).returning()
  return toStaffMemberDetail(created)
}

// ---------------------------------------------------------------------------
// Functions — paginated management list
// ---------------------------------------------------------------------------

/**
 * Get paginated staff member list with optional search filtering.
 *
 * Returns full StaffMemberDetail records suitable for the management view.
 * Search filters by name using SQL LIKE. Includes both active and inactive members.
 *
 * @param query - Optional search term, page number, and page size
 * @returns Paginated response with staff members and pagination metadata
 */
export async function listUsersPaginated(
  query: StaffListQuery = {}
): Promise<StaffPaginatedResponse> {
  const { search, page = 1, pageSize = 25 } = query
  const offset = (page - 1) * pageSize

  // Build filter conditions for search
  let whereClause: ReturnType<typeof sql> | undefined

  if (search && search.trim()) {
    const term = `%${search.trim()}%`
    whereClause = sql`LOWER(${users.name}) LIKE ${term.toLowerCase()}`
  }

  // Get total count for pagination
  let totalCount = 0
  if (whereClause) {
    const [{ count }] = await db.select({ count: sql<number>`count(*)` }).from(users).where(whereClause)
    totalCount = count
  } else {
    const [{ count }] = await db.select({ count: sql<number>`count(*)` }).from(users)
    totalCount = count
  }

  // Get paginated results
  let results: DbUser[]
  if (whereClause) {
    results = await db.select().from(users).where(whereClause)
      .orderBy(asc(users.name))
      .limit(pageSize)
      .offset(offset)
  } else {
    results = await db.select().from(users)
      .orderBy(asc(users.name))
      .limit(pageSize)
      .offset(offset)
  }

  const totalPages = Math.max(1, Math.ceil(totalCount / pageSize))

  return {
    users: results.map(toStaffMemberDetail),
    totalItems: totalCount,
    currentPage: page,
    pageSize,
    totalPages,
  }
}

// ---------------------------------------------------------------------------
// Custom Error Classes
// ---------------------------------------------------------------------------

export class StaffNotFoundError extends Error {
  constructor(public readonly id: string) {
    super(`Staff member not found: ${id}`)
    this.name = 'StaffNotFoundError'
  }
}

// ---------------------------------------------------------------------------
// Functions — get by ID
// ---------------------------------------------------------------------------

/**
 * Get a single staff member by ID.
 *
 * @throws StaffNotFoundError if user doesn't exist
 */
export async function getUserById(id: string): Promise<StaffMemberDetail> {
  const [user] = await db.select().from(users).where(eq(users.id, id))

  if (!user) {
    throw new StaffNotFoundError(id)
  }

  return toStaffMemberDetail(user)
}

// ---------------------------------------------------------------------------
// Functions — update staff member (partial)
// ---------------------------------------------------------------------------

/**
 * Update an existing staff member with partial fields.
 *
 * Only provided fields are changed. Validates against Zod schema which requires
 * at least one field to be present.
 *
 * @throws StaffNotFoundError if user doesn't exist
 * @throws ZodError if validation fails (empty payload, invalid role, etc.)
 */
export async function updateUser(
  id: string,
  input: UpdateStaffMemberInput,
): Promise<StaffMemberDetail> {
  // Validate — ensures at least one field is provided and values are valid
  const validated = updateStaffMemberSchema.parse(input)

  // Build partial DB update object (only include defined fields)
  const dbUpdate: Record<string, unknown> = {}
  if (validated.name !== undefined) dbUpdate.name = validated.name
  if (validated.role !== undefined) dbUpdate.role = validated.role as 'mechanic' | 'manager'
  if (validated.hourlyRate !== undefined) dbUpdate.hourlyRate = validated.hourlyRate
  if (validated.isActive !== undefined) dbUpdate.isActive = validated.isActive

  const [updated] = await db
    .update(users)
    .set(dbUpdate)
    .where(eq(users.id, id))
    .returning()

  if (!updated) {
    throw new StaffNotFoundError(id)
  }

  return toStaffMemberDetail(updated)
}

// ---------------------------------------------------------------------------
// Helpers — map between DB User and DTO shapes
// ---------------------------------------------------------------------------

/** Map a DB User to the full staff member detail shape. */
function toStaffMemberDetail(user: DbUser): StaffMemberDetail {
  return {
    id: user.id,
    name: user.name,
    role: user.role as 'mechanic' | 'manager',
    hourlyRate: user.hourlyRate,
    isActive: user.isActive,
    createdAt: user.createdAt,
  }
}

/**
 * Users Routes — Worker lookup for repair assignment and staff management.
 */

import { Hono } from 'hono'
import {
  getActiveWorkers,
  listUsersPaginated,
  createUser,
  updateUser,
  StaffNotFoundError,
  type StaffListQuery,
} from '../services/users.service.js'
import { createStaffMemberSchema, updateStaffMemberSchema } from '@shared/validations/staff.js'

const usersRoutes = new Hono()

// ---------------------------------------------------------------------------
// GET /users — Dual-mode endpoint
//
// When called without query parameters, returns a compact shape:
// id, name, role. Only active workers (isActive=true).
// Suitable for populating repair assignment dropdowns.
//
// When called with ?search= and/or ?page= parameters, returns full staff member
// details with pagination — suitable for the management list view.
// ---------------------------------------------------------------------------

usersRoutes.get('/', async (c) => {
  const search = c.req.query('search')
  const page = c.req.query('page')
  const pageSize = c.req.query('pageSize')

  // If pagination or search params are present, return paginated full details
  if (search !== undefined || page !== undefined || pageSize !== undefined) {
    const query: StaffListQuery = {}
    if (search !== undefined && search !== '') query.search = search
    if (page !== undefined) query.page = parseInt(page, 10)
    if (pageSize !== undefined) query.pageSize = parseInt(pageSize, 10)

    return c.json(await listUsersPaginated(query))
  }

  // Default: compact selector shape for POS dropdown consumers
  const workers = await getActiveWorkers()
  return new Response(JSON.stringify(workers), {
    headers: { 'Content-Type': 'application/json' },
  })
})

// ---------------------------------------------------------------------------
// POST /users — Create a new staff member
// ---------------------------------------------------------------------------

usersRoutes.post('/', async (c) => {
  const input = await c.req.json()

  try {
    const validated = createStaffMemberSchema.parse(input)
    const user = await createUser(validated)
    return c.json(user, 201)
  } catch (err) {
    if (err instanceof SyntaxError) {
      // Invalid JSON body
      return c.json({ error: 'Invalid request body', code: 'VALIDATION_ERROR' }, 400)
    }
    // Zod validation error
    return c.json({ error: 'Validation failed', code: 'VALIDATION_ERROR' }, 400)
  }
})

// ---------------------------------------------------------------------------
// PATCH /users/:id — Update a staff member (partial update)
// ---------------------------------------------------------------------------

usersRoutes.patch('/:id', async (c) => {
  const id = c.req.param('id')

  try {
    const input = await c.req.json()
    const validated = updateStaffMemberSchema.parse(input)
    const user = await updateUser(id, validated)
    return c.json(user)
  } catch (err) {
    if (err instanceof SyntaxError) {
      // Invalid JSON body
      return c.json({ error: 'Invalid request body', code: 'VALIDATION_ERROR' }, 400)
    }

    if (err instanceof StaffNotFoundError) {
      return c.json({ error: 'Staff member not found', code: 'NOT_FOUND' }, 404)
    }

    // Zod validation error
    return c.json({ error: 'Validation failed', code: 'VALIDATION_ERROR' }, 400)
  }
})

export default usersRoutes

