import { describe, it, expect, beforeEach } from 'vitest'
import crypto from 'crypto'
import type Database from 'better-sqlite3'
import { db, sqliteDb } from '@/db/index.js'
import { workLogs, users, repairs as repairsTable } from '@/db/schema.js'

// Raw SQL executor — avoids Drizzle Date/number conversion issues with timestamps
function run(sqlStr: string, params?: unknown[]): void {
  const client = sqliteDb as Database.Database
  client.prepare(sqlStr).run(...(params ?? []))
}

// ---------------------------------------------------------------------------
// Helpers — create test fixtures in the DB
// ---------------------------------------------------------------------------

async function seedUser(): Promise<string> {
  const id = crypto.randomUUID()
  await db.insert(users).values({
    id,
    name: 'Test Technician',
    role: 'mechanic',
    hourlyRate: 5000, // 50 EUR/hour in cents
  })
  return id
}

/** Insert a repair with raw SQL (avoids Drizzle type issues) */
function insertRepair(repairId: string, bicycleId: string, assignedTo: string | null, status: string): void {
  const now = Date.now()
  run(
    'INSERT INTO repairs (id, bicycle_id, assigned_to, status, customer_notes, internal_notes, hold_reason, hold_reason_note, planned_date, pickup_date, completed_at, created_at) VALUES (?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?)',
    [repairId, bicycleId, assignedTo, status, null, null, null, null, null, null, null, now]
  )
}

async function seedRepair(assignedTo: string | null, status = 'in_progress'): Promise<string> {
  const id = crypto.randomUUID()
  insertRepair(id, 'bicycle-placeholder-id', assignedTo, status)
  return id
}

/** Insert a work log with raw SQL */
function insertWorkLog(workLogId: string, repairId: string, userId: string, startedAt: number, endedAt: number | null): void {
  run(
    'INSERT INTO work_logs (id, repair_id, user_id, started_at, ended_at) VALUES (?, ?, ?, ?, ?)',
    [workLogId, repairId, userId, startedAt, endedAt]
  )
}

async function resetData() {
  await db.delete(workLogs)
  // Clean repairs by raw SQL (Drizzle doesn't support delete-all easily on some tables)
  run('DELETE FROM repairs')
  await db.delete(users)
}

// ---------------------------------------------------------------------------
// Tests — computeStaffStats
// ---------------------------------------------------------------------------

describe('computeStaffStats', async () => {
  const { computeStaffStats } = await import('../users.service.js')

  beforeEach(async () => {
    await resetData()
  })

  describe('zero repairs (all zeros/nulls)', () => {
    it('should return zero hours, zero repairs, null avg when user has no data', async () => {
      const userId = await seedUser()

      const stats = await computeStaffStats(userId)

      expect(stats.totalHoursWorked).toBe(0)
      expect(stats.completedRepairs).toBe(0)
      expect(stats.activeRepairs).toBe(0)
      expect(stats.avgRepairDurationMinutes).toBeNull()
    })
  })

  describe('single completed repair with one work log', () => {
    it('should return correct hours and counts for one completed repair', async () => {
      const userId = await seedUser()
      const repairId = await seedRepair(userId, 'completed')

      // Insert a work log: 60 minutes (3600000 ms)
      const startedAt = Date.now() - 3_600_000
      insertWorkLog(crypto.randomUUID(), repairId, userId, startedAt, startedAt + 3_600_000)

      const stats = await computeStaffStats(userId)

      expect(stats.totalHoursWorked).toBe(60) // minutes
      expect(stats.completedRepairs).toBe(1)
      expect(stats.activeRepairs).toBe(0)
      expect(stats.avgRepairDurationMinutes).toBe(60) // 60 / 1 = 60
    })
  })

  describe('multiple repairs with mixed statuses', () => {
    it('should count completed and active correctly, exclude cancelled from both', async () => {
      const userId = await seedUser()

      // 2 completed repairs
      const completed1 = await seedRepair(userId, 'completed')
      const completed2 = await seedRepair(userId, 'completed')

      // 1 in_progress repair (active)
      await seedRepair(userId, 'in_progress')

      // 1 on_hold repair (active — not completed/cancelled)
      await seedRepair(userId, 'on_hold')

      // 1 cancelled repair (should be excluded from both counts)
      await seedRepair(userId, 'cancelled')

      // Work logs: 30 min for completed1, 20 min for completed2 = 50 min total
      const now = Date.now()
      insertWorkLog(crypto.randomUUID(), completed1, userId, now - 1_800_000, now) // 30 min
      insertWorkLog(crypto.randomUUID(), completed2, userId, now - 1_200_000, now) // 20 min

      const stats = await computeStaffStats(userId)

      expect(stats.totalHoursWorked).toBe(50) // minutes
      expect(stats.completedRepairs).toBe(2)
      expect(stats.activeRepairs).toBe(2) // in_progress + on_hold
      expect(stats.avgRepairDurationMinutes).toBe(25) // 50 / 2 = 25
    })

    it('should exclude running timers (null endedAt) from totalHoursWorked', async () => {
      const userId = await seedUser()
      const repairId = await seedRepair(userId, 'in_progress')

      const now = Date.now()
      // Completed work log: 30 min
      insertWorkLog(crypto.randomUUID(), repairId, userId, now - 1_800_000, now)
      // Running timer (null endedAt): should be excluded
      insertWorkLog(crypto.randomUUID(), repairId, userId, now - 600_000, null)

      const stats = await computeStaffStats(userId)

      expect(stats.totalHoursWorked).toBe(30) // only the completed work log
    })

    it('should return null avgRepairDurationMinutes when no completions', async () => {
      const userId = await seedUser()

      // Only active repairs, no completed ones
      await seedRepair(userId, 'in_progress')
      await seedRepair(userId, 'on_hold')

      // Work log exists but repair is not completed
      const repairId = await seedRepair(userId, 'intake')
      const now = Date.now()
      insertWorkLog(crypto.randomUUID(), repairId, userId, now - 1_800_000, now)

      const stats = await computeStaffStats(userId)

      expect(stats.totalHoursWorked).toBe(30) // work log still counted
      expect(stats.completedRepairs).toBe(0)
      expect(stats.activeRepairs).toBe(3)
      expect(stats.avgRepairDurationMinutes).toBeNull() // 0 completions → null
    })
  })

  describe('cancelled repairs excluded from active count', () => {
    it('should not count cancelled repairs as active', async () => {
      const userId = await seedUser()

      await seedRepair(userId, 'cancelled')
      await seedRepair(userId, 'cancelled')
      await seedRepair(userId, 'in_progress') // only this one is active

      const stats = await computeStaffStats(userId)

      expect(stats.completedRepairs).toBe(0)
      expect(stats.activeRepairs).toBe(1) // only in_progress counts
    })
  })
})

