/** Aggregated performance statistics for a single staff member. */
export interface StaffStats {
  /** Total minutes worked from completed work log timers (endedAt IS NOT NULL) */
  totalHoursWorked: number
  /** Count of repairs assigned to this user with status = 'completed' */
  completedRepairs: number
  /** Count of repairs assigned to this user where status is NOT 'completed' or 'cancelled' */
  activeRepairs: number
  /** Average repair duration in minutes (totalHoursWorked / completedRepairs), null if no completions */
  avgRepairDurationMinutes: number | null
}

// ---------------------------------------------------------------------------
// Functions — staff stats aggregation (pure computation, no side effects)
// ---------------------------------------------------------------------------

/**
 * Aggregate staff performance statistics from workLogs and repairs.
 *
 * Pure computation function — reads data but produces no side effects.
 * - totalHoursWorked: SUM of (endedAt - startedAt) in minutes from completed work logs
 * - completedRepairs: COUNT of assigned repairs with status = 'completed'
 * - activeRepairs: COUNT of assigned repairs NOT in ('completed', 'cancelled')
 * - avgRepairDurationMinutes: totalHoursWorked / completedRepairs (null if 0 completions)
 */
export async function computeStaffStats(userId: string): Promise<StaffStats> {
  // Total minutes worked from completed work log timers
  const [{ totalMs }] = await db
    .select({ totalMs: sql<number>`COALESCE(SUM(${workLogs.endedAt} - ${workLogs.startedAt}), 0)` })
    .from(workLogs)
    .where(
      sql`${workLogs.userId} = ${userId} AND ${workLogs.endedAt} IS NOT NULL`
    )

  const totalHoursWorked = Math.round(totalMs / 60_000) // ms → minutes, rounded

  // Completed repairs count
  const [{ completedCount }] = await db
    .select({ completedCount: sql<number>`count(*)` })
    .from(repairs)
    .where(
      sql`${repairs.assignedTo} = ${userId} AND ${repairs.status} = 'completed'`
    )

  // Active repairs count (not completed, not cancelled)
  const [{ activeCount }] = await db
    .select({ activeCount: sql<number>`count(*)` })
    .from(repairs)
    .where(
      sql`${repairs.assignedTo} = ${userId} AND ${repairs.status} NOT IN ('completed', 'cancelled')`
    )

  const completedRepairs = completedCount
  const activeRepairs = activeCount
  const avgRepairDurationMinutes = completedRepairs > 0 ? totalHoursWorked / completedRepairs : null

  return { totalHoursWorked, completedRepairs, activeRepairs, avgRepairDurationMinutes }
}

// ---------------------------------------------------------------------------
// GET /users/:id/stats — Staff performance statistics
// ---------------------------------------------------------------------------

usersRoutes.get('/:id/stats', async (c) => {
  const id = c.req.param('id')

  // Verify user exists before computing stats
