  updateUser,
  computeStaffStats,
  StaffNotFoundError,
  type StaffListQuery,
} from '../services/users.service.js'
import { createStaffMemberSchema, updateStaffMemberSchema } from '@shared/validations/staff.js'

const usersRoutes = new Hono()

// ---------------------------------------------------------------------------
// GET /users — Dual-mode endpoint
//
// When called without query parameters, returns a compact shape:
// id, name, role. Only active workers (isActive=true).
// Suitable for populating repair assignment dropdowns.
//
// When called with ?search= and/or ?page= parameters, returns full staff member
// details with pagination — suitable for the management list view.
// ---------------------------------------------------------------------------

usersRoutes.get('/', async (c) => {
  const search = c.req.query('search')
  const page = c.req.query('page')
  const pageSize = c.req.query('pageSize')

  // If pagination or search params are present, return paginated full details
  if (search !== undefined || page !== undefined || pageSize !== undefined) {
    const query: StaffListQuery = {}
    if (search !== undefined && search !== '') query.search = search
    if (page !== undefined) query.page = parseInt(page, 10)
    if (pageSize !== undefined) query.pageSize = parseInt(pageSize, 10)

    return c.json(await listUsersPaginated(query))
  }

  // Default: compact selector shape for POS dropdown consumers
  const workers = await getActiveWorkers()
  return new Response(JSON.stringify(workers), {
    headers: { 'Content-Type': 'application/json' },
  })
})

// ---------------------------------------------------------------------------
// POST /users — Create a new staff member
// ---------------------------------------------------------------------------

usersRoutes.post('/', async (c) => {
  const input = await c.req.json()

  try {
    const validated = createStaffMemberSchema.parse(input)
    const user = await createUser(validated)
    return c.json(user, 201)
  } catch (err) {
    if (err instanceof SyntaxError) {
      // Invalid JSON body
      return c.json({ error: 'Invalid request body', code: 'VALIDATION_ERROR' }, 400)
    }
    // Zod validation error
    return c.json({ error: 'Validation failed', code: 'VALIDATION_ERROR' }, 400)
  }
})

// ---------------------------------------------------------------------------
// PATCH /users/:id — Update a staff member (partial update)
// ---------------------------------------------------------------------------

usersRoutes.patch('/:id', async (c) => {
  const id = c.req.param('id')

  try {
    const input = await c.req.json()
    const validated = updateStaffMemberSchema.parse(input)
    const user = await updateUser(id, validated)
    return c.json(user)
  } catch (err) {
    if (err instanceof SyntaxError) {
      // Invalid JSON body
      return c.json({ error: 'Invalid request body', code: 'VALIDATION_ERROR' }, 400)
    }

    if (err instanceof StaffNotFoundError) {
      return c.json({ error: 'Staff member not found', code: 'NOT_FOUND' }, 404)
    }

    // Zod validation error
    return c.json({ error: 'Validation failed', code: 'VALIDATION_ERROR' }, 400)
  }
})

